const $=s=>document.querySelector(s);
let installed=false,filter='all',current='original',demoStarted=false;
const conversations=[{id:'original',name:'林遥的故事',enabled:true,draft:''}];
function active(){return conversations.find(c=>c.id===current);}
function market(){ $('#count').textContent=installed?'1':'0';$('#install-state').textContent=installed?'已安装 · v1.0.0':'尚未安装';$('#install').textContent=installed?'卸载插件':'安装插件';$('.plugin').hidden=filter==='installed'&&!installed;$('#empty').hidden=filter!=='installed'||installed; }
function render(){const c=active();$('#route-name').textContent=c.name;$('#active-state').textContent=installed?(c.enabled?'已启用':'未启用'):'尚未安装';$('#enable').textContent=c.enabled&&installed?'停用':'启用';$('#branch-open').disabled=!installed||!c.enabled;$('#branch-open').title=installed&&c.enabled?'从此回合创建新对话':'请在本会话插件设置中启用分支存档';$('#conversation-list').replaceChildren();for(const item of conversations){const row=document.createElement('div');row.className='conversation-row';const button=document.createElement('button');button.textContent=item.name;button.onclick=()=>{switchTo(item.id);$('#list-dialog').close();};const state=document.createElement('span');state.textContent=item.id===current?'当前':'';row.append(button,state);$('#conversation-list').append(row);}}
function switchTo(id){active().draft=$('#input').value;current=id;$('#input').value=active().draft;render();}
function view(name){if(name!=='market'&&!demoStarted){installed=true;demoStarted=true;market();}$('#market').hidden=name!=='market';$('#chat').hidden=name==='market';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===name)));render();location.hash=name;if(name==='list')$('#list-dialog').showModal();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));market();});
$('#install').onclick=()=>{installed=!installed;if(!installed)for(const c of conversations)c.enabled=false;market();render();$('#market-feedback').textContent=installed?'原型演示：安装完成，在会话内单独启用。':'原型演示：已卸载，原对话和分支保留。';};
$('#enable').onclick=()=>{if(!installed){$('#plugin-dialog').close();view('market');$('#market-feedback').textContent='请先安装分支存档。';return;}active().enabled=!active().enabled;render();};
$('#branch-open').onclick=()=>{if(!installed||!active().enabled)return;$('#branch-name').value=active().name+'-分支';$('#draft-note').hidden=!$('#input').value.trim();$('#branch-dialog').showModal();};
$('#branch-form').onsubmit=e=>{e.preventDefault();const name=$('#branch-name').value.trim();if(!name)return;const next={id:crypto.randomUUID(),name,enabled:false,draft:''};conversations.unshift(next);switchTo(next.id);$('#branch-dialog').close();$('#chat-feedback').textContent='分支已创建，可从对话列表返回原对话。';};
$('#list-open').onclick=()=>{render();$('#list-dialog').showModal();};$('#plugin-open').onclick=()=>{render();$('#plugin-dialog').showModal();};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#raw').onclick=()=>$('#chat-feedback').textContent='本页为虚构原型正文，没有真实模型输出。';
market();view(['market','chat','list'].includes(location.hash.slice(1))?location.hash.slice(1):'chat');
